const hovertxt = document.querySelector(".hovtxt");
const hovertext = document.createElement("div");

hovertext.style.position = "absolute";
hovertext.style.display = "none";
hovertext.style.zIndex = "999";
hovertext.style.background = "#fff";
hovertext.style.padding = "5px";
hovertext.style.border = "1px solid #ccc";
hovertext.innerHTML = "<i>This is the person you report to in your main paid job for direct work tasks and guidance. Your main paid job is the employment in which you are working the most hours.</i>";

document.body.appendChild(hovertext);

hovertxt.addEventListener("mouseover", (e) => {
    hovertext.style.display = "block";
    hovertext.style.top = `${e.pageY + 10}px`;
    hovertext.style.left = `${e.pageX + 10}px`;
});

hovertxt.addEventListener("mousemove", (e) => {
    hovertext.style.top = `${e.pageY + 10}px`;
    hovertext.style.left = `${e.pageX + 10}px`;
});

hovertxt.addEventListener("mouseout", () => {
    hovertext.style.display = "none";
});

