// --- Helpers ---
function addDaysUTC(date, days) {
  // Build a UTC date at midnight to avoid DST/local-time drift
  const d = new Date(Date.UTC(
    date.getUTCFullYear(),
    date.getUTCMonth(),
    date.getUTCDate()
  ));
  d.setUTCDate(d.getUTCDate() + Number(days || 0));
  return d;
}

function formatDateUTC(d) {
  const dd = String(d.getUTCDate()).padStart(2, '0');
  const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
  const yyyy = d.getUTCFullYear();
  return `${yyyy}-${mm}-${dd}`;
}

// --- Compute: today + 14 days (UTC-normalized) ---
const today = new Date();
const reminderUTC = addDaysUTC(today, 14);

// For a Date variable in Forsta, setting an ISO date-only string ("YYYY-MM-DD")
// avoids time components and timezone shifts.
const isoDateOnly = reminderUTC.toISOString().slice(0, 10); // e.g., "2026-03-09"

// Save to Date variable
f('Reminderdate').set(isoDateOnly);

// --- Write formatted text ("dd-mm-yyyy") into AUTH_R1_DATE ---
function coerceToDateUTC(value) {
  // Accept Date object or string
  if (value instanceof Date) return value;
  const d = new Date(value);
  return isNaN(d) ? null : d;
}

// Read back Reminderdate and format safely
const reminderVal = f('Reminderdate').get();
const reminderDate = coerceToDateUTC(reminderVal) || reminderUTC;

f('AUTH_R1_DATE').set(formatDateUTC(reminderDate));

